  recordedAudio.onended=()=>{if(token===audioToken)audioStatus('Đã đọc đáp án đúng · Bấm Nghe lại để nghe thêm.');};
  audioStatus('Đang phát đáp án đúng…');recordedAudio.play().catch(()=>{if(token===audioToken)audioStatus('Bấm Nghe lại để bật âm thanh; kiểm tra âm lượng thiết bị.');});return;
