  utter.onerror=e=>{if(token===audioToken&&!['canceled','interrupted'].includes(e.error))audioStatus('Chưa phát được giọng Nhật. Bấm Nghe lại; kiểm tra âm lượng hoặc giọng đọc tiếng Nhật trên thiết bị.');};
