function renderQuestion(){
 const v=deck[at],f=activeForm();loadAudio(conjugate(v,form)[0].reading).catch(()=>{});checked=false;$('rules').classList.add('hidden');$('rules').open=false;options=makeChoices(v,form);
 $('practice').innerHTML='<div class="card-head"><div class="target">CHUYỂN SANG <strong>'+f[1].toLocaleUpperCase('vi-VN')+' · '+f[2]+'</strong></div><span class="counter"><b>'+String(at+1).padStart(2,'0')+'</b> / 10</span></div><div class="question"><span class="group">ĐỘNG TỪ '+level+'</span><div class="word" lang="ja">'+ruby(v.masu,v.masuReading)+'</div><p class="meaning">'+esc(v.meaning)+'</p></div><section class="answer-form"><div class="input-label"><span>Chọn 1 trong 3 đáp án</span><span>Cùng dạng đuôi · Chọn xong nghe đáp án đúng</span></div><div class="choices" role="group" aria-label="Ba đáp án">'+options.map((a,i)=>'<button type="button" class="choice" data-choice="'+i+'" aria-pressed="false"><span class="letter" aria-hidden="true">'+['A','B','C'][i]+'</span><span class="choice-word" lang="ja">'+ruby(a.surface,a.reading)+'</span></button>').join('')+'</div><div id="feedback" class="feedback" role="status" aria-live="polite"></div><div class="after-answer hidden" id="afterAnswer"><button type="button" class="listen" id="listen">◖)) Nghe lại</button><span id="audioStatus" role="status"></span><button type="button" class="next" id="next">'+(at===9?'Xem kết quả →':'Câu tiếp theo →')+'</button></div></section><div class="bottom"><span><kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd> Chọn đáp án · <kbd>Enter</kbd> Câu tiếp theo</span><span id="scoreLive">Đúng <b>'+results.filter(r=>r.correct).length+'</b> / '+results.length+' câu đã làm</span></div><div class="progress" aria-label="Tiến độ" role="progressbar" aria-valuemin="0" aria-valuemax="10" aria-valuenow="'+at+'"><i style="width:'+(at*10)+'%"></i></div>';
 $('practice').querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>selectAnswer(Number(b.dataset.choice)));
 $('listen').onclick=readAnswer;$('next').onclick=next;
}
function selectAnswer(index){
 if(checked||complete||!options[index])return;const v=deck[at],choice=options[index],correct=matches(v,form,choice.reading),answers=conjugate(v,form);
 $('rules').classList.remove('hidden');checked=true;results.push({v,choice,value:choice.surface,correct});
 $('practice').querySelectorAll('[data-choice]').forEach((b,i)=>{b.disabled=true;const right=matches(v,form,options[i].reading);b.classList.toggle('correct',right);b.classList.toggle('wrong',i===index&&!right);b.setAttribute('aria-pressed',String(i===index));});
 $('feedback').className='feedback '+(correct?'good':'bad');
 $('feedback').innerHTML='<div class="status">'+(correct?'✓ Chính xác!':'Chưa đúng — cùng nghe đáp án đúng nhé')+'</div><div class="answer-line">Đáp án đúng: <span class="solution" lang="ja">'+answers.map(a=>ruby(a.surface,a.reading)).join(' <span class="or">hoặc</span> ')+'</span></div><details class="explain" open><summary>Nhóm '+['I','II','III'][v.group-1]+' · Vì sao chia như vậy?</summary>'+explanation(v,form)+'</details>';
 $('afterAnswer').classList.remove('hidden');$('scoreLive').innerHTML='Đúng <b>'+results.filter(r=>r.correct).length+'</b> / '+results.length+' câu đã làm';
 const bar=$('practice').querySelector('[role="progressbar"]');bar.setAttribute('aria-valuenow',String(at+1));bar.querySelector('i').style.width=(at+1)*10+'%';
 readAnswer();
 $('feedback').scrollIntoView({block:'nearest',behavior:'smooth'});
}
function next(){if(!checked)return;stopSpeech();if(at===9){complete=true;renderResults();return;}at++;renderQuestion();}
document.addEventListener('keydown',e=>{
 if(e.repeat||e.ctrlKey||e.altKey||e.metaKey)return;
 if(['1','2','3'].includes(e.key)&&!complete){e.preventDefault();selectAnswer(Number(e.key)-1);}
 if(e.key==='Enter'&&checked&&!complete&&document.activeElement?.id!=='listen'){e.preventDefault();next();}
});

function renderResults(){const score=results.filter(r=>r.correct).length;
 $('practice').innerHTML='<div class="result"><div class="group">HOÀN THÀNH · '+activeForm()[1].toUpperCase()+'</div><h2>'+ (score>=8?'Làm tốt lắm!':'Thêm một lượt để nhớ chắc hơn nhé!')+'</h2><div class="score">'+score+'<span style="font-size:25px;color:#92abc9"> / 10</span></div><p>Mỗi lượt mới sẽ chọn ngẫu nhiên 10 động từ khác nhau.</p><button class="again" id="again">↻ Luyện lượt mới</button><table class="review"><thead><tr><th>Động từ</th><th>Bạn đã chọn</th><th>Đáp án</th><th>Kết quả</th></tr></thead><tbody>'+results.map(r=>'<tr><td lang="ja">'+ruby(r.v.masu,r.v.masuReading)+'</td><td>'+ruby(r.choice.surface,r.choice.reading)+'</td><td lang="ja">'+conjugate(r.v,form).map(a=>ruby(a.surface,a.reading)).join(' / ')+'</td><td class="'+(r.correct?'ok':'wrong')+'">'+(r.correct?'✓ Đúng':'Ôn lại')+'</td></tr>').join('')+'</tbody></table></div>';
 $('again').onclick=()=>start();
}
document.querySelectorAll('[data-level]').forEach(b=>{b.onclick=()=>{level=b.dataset.level;start();};b.onkeydown=e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();level=level==='N5'?'N4':'N5';start();$('tab'+level).focus();}};});
start();

document.documentElement.dataset.diaryActivity='Ngữ pháp · Luyện chia thể';
window.addEventListener('pagehide',stopSpeech);
